// Straight-line distance in km between two [lat, lng] points
export function haversineKm(a, b) {
  const R = 6371;
  const dLat = ((b[0] - a[0]) * Math.PI) / 180;
  const dLng = ((b[1] - a[1]) * Math.PI) / 180;
  const s1 = Math.sin(dLat / 2), s2 = Math.sin(dLng / 2);
  const h = s1 * s1 + Math.cos((a[0] * Math.PI) / 180) * Math.cos((b[0] * Math.PI) / 180) * s2 * s2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

// Fallback round-trip AC-bus fare estimate (BDT) when a route has no researched baseline.
// Calibrated against researched baselines (~9 BDT per km of straight-line distance).
export function estimateRoadFare(originCoords, destCoords) {
  const km = haversineKm(originCoords, destCoords);
  return Math.max(600, Math.round((km * 9) / 100) * 100);
}
